import json
from itertools import product

# Each individual is a tuple (L, M, T, W). Model: John plus one other employee.
# Premises: for all x, L->M and T->W; exists x with not M and not W.
# Query: for John, (not L) or (not T).

def ok(p):
    L, M, T, W = p
    return (not L or M) and (not T or W)

people = list(product([False, True], repeat=4))
valid = [p for p in people if ok(p)]

counter = None
entailed = True
for john in valid:
    for other in valid:
        if any((not x[1]) and (not x[3]) for x in (john, other)):
            L, M, T, W = john
            if not ((not L) or (not T)):
                entailed = False
                counter = {"john": john, "other": other}
                break
    if counter:
        break

print(json.dumps({
    "final_answer": "yes" if entailed else "no",
    "evidence": {"entailed": entailed, "counter_model(L,M,T,W)": counter}
}))
